/** Second-order Butterworth lowpass. alias for designLowpass with Q=1/sqrt(2). */
function butterworthLowpass(fc, fs = 1) {
  void fs;
  return designLowpass(fc, Math.SQRT1_2);
}

/**
 * Second-order Chebyshev Type I lowpass via analog prototype poles and a
 * prewarped bilinear transform.
 *
 * Analog prototype: s^2 + a1*s + a0 with poles
 *   s = -sinh(v)*sin(pi/4) +/- j*cosh(v)*cos(pi/4),
 * where v = asinh(1/eps)/2 and eps = sqrt(10^(rippleDb/10) - 1).
 * Scaling the prototype to wc = 2*tan(w0/2) with w0 = 2*PI*fc and
 * substituting s = 2*(z-1)/(z+1) keeps the ripple band ending at fc.
 * Because order 2 is even, the unscaled passband maximum is +rippleDb at
 * DC. The numerator is scaled by 10^(rippleDb/20) so the passband maximum
 * is 0 dB, matching the Butterworth reference; DC then sits at -rippleDb.
 */
function chebyshevLowpass(fc, rippleDb = 1, fs = 1) {
  void fs;
  validateCutoff(fc);
  if (!isFiniteNumber(rippleDb) || rippleDb < 1e-6 || rippleDb > 20) {
    throw new RangeError('rippleDb must be in [1e-6, 20]');
  }
  const eps = Math.sqrt(Math.pow(10, rippleDb / 10) - 1);
  const v = Math.asinh(1 / eps) / 2;
  const sh = Math.sinh(v), ch = Math.cosh(v);
  const sr = -sh * Math.SQRT1_2, si = ch * Math.SQRT1_2;
  const a1Analog = -2 * sr;
  const a0Analog = sr * sr + si * si;
  // Prewarp at the digital cutoff w0 = 2*PI*fc so the ripple band ends at fc.
  const w0 = TAU * fc, wc = 2 * Math.tan(w0 / 2), k = 2;
  const A1 = a1Analog * wc, A0 = a0Analog * wc * wc, K = a0Analog * wc * wc;
  const d0 = k * k + A1 * k + A0;
  const d1 = -2 * k * k + 2 * A0;
  const d2 = k * k - A1 * k + A0;
  let b0 = K / d0, b1 = 2 * K / d0, b2 = K / d0;
  const a1 = d1 / d0, a2 = d2 / d0;
  // Even-order Chebyshev has a passband maximum at DC. Scale the numerator
  // so the passband maximum is 0 dB, matching the Butterworth reference.
  // The passband then spans -rippleDb .. 0 dB and DC sits at -rippleDb.
  const normalize = Math.pow(10, rippleDb / 20);
  b0 /= normalize; b1 /= normalize; b2 /= normalize;
  return { b0, b1, b2, a1, a2 };
}

/** Select a design family by name. */
function designFilter(options = {}) {
  const family = options.family ?? 'butterworth';
  const fc = options.fc ?? 0.2;
  if (family === 'butterworth') return butterworthLowpass(fc);
  if (family === 'chebyshev') return chebyshevLowpass(fc, options.rippleDb ?? 1);
  if (family === 'highpass') return designHighpass(fc, options.Q ?? Math.SQRT1_2);
  if (family === 'bandpass') return designBandpass(fc, options.Q ?? 2);
  throw new RangeError(`unknown filter family: ${family}`);
}

/* -------------------------------------------------------------------------- */
/* Pole-zero, response and stability                                          */
/* -------------------------------------------------------------------------- */

function quadraticRoots(a, b, c) {
  // Roots of a*z^2 + b*z + c = 0, returned as complex pairs.
  if (Math.abs(a) < EPS) return [{ real: -c / b, imag: 0 }, { real: -c / b, imag: 0 }];
  const disc = b * b - 4 * a * c;
  if (disc >= 0) {
    const s = Math.sqrt(disc);
    return [{ real: (-b + s) / (2 * a), imag: 0 }, { real: (-b - s) / (2 * a), imag: 0 }];
  }
  const re = -b / (2 * a), im = Math.sqrt(-disc) / (2 * Math.abs(a));
  return [{ real: re, imag: im }, { real: re, imag: -im }];
}

function biquadPoleZero(coeffs) {
  const { b0, b1, b2, a1, a2 } = coeffs;
  return {
    zeros: quadraticRoots(b0, b1, b2),
    poles: quadraticRoots(1, a1, a2)
  };
}

/** Jury stability criterion for a real second-order denominator. */
function biquadStability(coeffs) {
  const { a1, a2 } = coeffs;
  const jury = 1 + a1 + a2 > -EPS && 1 - a1 + a2 > -EPS && 1 - a2 > -EPS;
  const { poles, zeros } = biquadPoleZero(coeffs);
  const maxPoleRadius = Math.max(...poles.map(p => Math.hypot(p.real, p.imag)));
  const minPhase = zeros.every(z => Math.hypot(z.real, z.imag) <= 1 + 1e-9);
  return { stable: jury && maxPoleRadius < 1, jury, maxPoleRadius, minPhase, poles, zeros };
}

/**
 * Exact complex frequency response of a biquad, plus analytic group delay.
 *
 * B(z) = sum b_k z^-k, A(z) = sum a_k z^-k with a0 = 1.
 * Let D = d/dw and z = e^(jw). Then
 *   D arg B = -Re( sum k b_k z^-k / B ),
 * and group delay = -D(arg B - arg A) = -D arg B + D arg A.
 */
function biquadFrequencyResponse(coeffs, w) {
  const B = [coeffs.b0, coeffs.b1, coeffs.b2];
  const A = [1, coeffs.a1, coeffs.a2];
  let br = 0, bi = 0, ar = 0, ai = 0;
  let dbr = 0, dbi = 0, dar = 0, dai = 0;
  for (let k = 0; k < 3; k++) {
    const c = Math.cos(k * w), s = -Math.sin(k * w);
    br += B[k] * c; bi += B[k] * s;
    ar += A[k] * c; ai += A[k] * s;
    dbr += -k * B[k] * c; dbi += -k * B[k] * s;
    dar += -k * A[k] * c; dai += -k * A[k] * s;
  }
  const b2 = br * br + bi * bi, a2 = ar * ar + ai * ai;
  const magnitude = Math.sqrt(b2 / a2);
  const phase = Math.atan2(bi, br) - Math.atan2(ai, ar);
  // -D arg B + D arg A. At an exact transmission zero B = 0, the analytic
  // expression is 0/0. Evaluate the limit from a nearby frequency instead of
  // emitting NaN, which would otherwise corrupt CSV and SVG exports.
  let groupDelay;
  if (b2 < 1e-24 || a2 < 1e-24) {
    const h = 1e-5;
    const near = biquadFrequencyResponse(coeffs, clamp(w + (w < PI * 0.5 ? h : -h), 0, PI));
    groupDelay = Number.isFinite(near.groupDelay) ? near.groupDelay : 0;
  } else {
    groupDelay = -(dbr * br + dbi * bi) / b2 + (dar * ar + dai * ai) / a2;
  }
  return { magnitude, phase, groupDelay };
}

function biquadBode(coeffs, nPoints = 512) {
  if (!Number.isInteger(nPoints) || nPoints < 2) throw new RangeError('nPoints must be >= 2');
  const freq = new Float64Array(nPoints), mag = new Float64Array(nPoints);
  const phase = new Float64Array(nPoints), grpDelay = new Float64Array(nPoints);
  for (let i = 0; i < nPoints; i++) {
    const w = PI * i / (nPoints - 1);
    freq[i] = w / PI;
    const r = biquadFrequencyResponse(coeffs, w);
    mag[i] = linearToDb(r.magnitude);
    phase[i] = r.phase;
    grpDelay[i] = r.groupDelay;
  }
  return { freq, mag, phase, grpDelay };
}

function poleZeroPlotData(coeffs) {
  const { zeros, poles } = biquadPoleZero(coeffs);
  return {
    zeros: zeros.map(z => ({ x: z.real, y: z.imag })),
    poles: poles.map(p => ({ x: p.real, y: p.imag })),
    unitCircle: Array.from({ length: 128 }, (_, i) => ({ x: Math.cos(TAU * i / 128), y: Math.sin(TAU * i / 128) }))
  };
}

/** Measured attenuation of a tone after filtering, plus input/output RMS. */
function filterDiagnostics(input, output, coeffs, toneHz, sampleRate) {
  const rms = arr => {
    let s = 0;
    for (let i = 0; i < arr.length; i++) s += arr[i] * arr[i];
    return Math.sqrt(s / Math.max(1, arr.length));
  };
  const w = TAU * clamp(toneHz / sampleRate, 0, 0.5);
  const predicted = biquadFrequencyResponse(coeffs, w);
  return {
    inputRms: rms(input), outputRms: rms(output),
    rmsRatio: rms(output) / (rms(input) || 1),
    predictedGainDb: linearToDb(predicted.magnitude),
    peakOutput: output.reduce((m, v) => Math.max(m, Math.abs(v)), 0),
    finite: output.every(Number.isFinite)
  };
}

/* -------------------------------------------------------------------------- */
/* Exporters                                                                  */
/* -------------------------------------------------------------------------- */

/** Escape one CSV field, quoting when needed. */
function csvField(value) {
  const s = String(value);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

function exportCHeader(coeffs, name = 'biquad') {
  for (const k of ['b0', 'b1', 'b2', 'a1', 'a2']) {
    if (!isFiniteNumber(coeffs[k])) throw new RangeError(`coefficient ${k} is not finite`);
  }
  let safe = String(name).replace(/[^A-Za-z0-9_]/g, '_');
  if (!/^[A-Za-z_]/.test(safe)) safe = '_' + safe;
  const upper = safe.toUpperCase();
  const guard = upper + '_H';
  const lines = [
    '/* Auto-generated biquad coefficients. a0 is normalized to 1. */',
    `#ifndef ${guard}`, `#define ${guard}`, '',
    `#define ${upper}_B0 ${coeffs.b0.toPrecision(12)}`,
    `#define ${upper}_B1 ${coeffs.b1.toPrecision(12)}`,
    `#define ${upper}_B2 ${coeffs.b2.toPrecision(12)}`,
    `#define ${upper}_A1 ${coeffs.a1.toPrecision(12)}`,
    `#define ${upper}_A2 ${coeffs.a2.toPrecision(12)}`, '',
    '/* Direct Form II Transposed */',
    `static inline float ${safe}_process(float x, float *w1, float *w2) {`,
    `    float y = ${upper}_B0 * x + *w1;`,
    `    *w1 = ${upper}_B1 * x - ${upper}_A1 * y + *w2;`,
    `    *w2 = ${upper}_B2 * x - ${upper}_A2 * y;`,
    '    return y;', '}', '', `#endif /* ${guard} */`, ''
  ];
  return lines.join('\n');
}

function exportCSV(coeffs, name = 'biquad') {
  const rows = [['coefficient', 'value']];
  for (const key of ['b0', 'b1', 'b2', 'a1', 'a2']) rows.push([`${name}_${key}`, String(coeffs[key])]);
  return rows.map(r => r.map(csvField).join(',')).join('\n') + '\n';
}

/** Bode table CSV: normalized frequency, magnitude dB, phase rad, group delay. */
function exportBodeCSV(bode) {
  const rows = [['freq_normalized', 'magnitude_db', 'phase_rad', 'group_delay_samples']];
  for (let i = 0; i < bode.freq.length; i++) {
    for (const key of ['freq', 'mag', 'phase', 'grpDelay']) {
      if (!Number.isFinite(bode[key][i])) throw new RangeError(`bode.${key}[${i}] is not finite`);
    }
    rows.push([bode.freq[i].toFixed(8), bode.mag[i].toFixed(8), bode.phase[i].toFixed(8), bode.grpDelay[i].toFixed(8)]);
  }
  return rows.map(r => r.join(',')).join('\n') + '\n';
}

/** Spectrum CSV with bin index, cycles/sample, Hz, magnitude and phase. */
function exportSpectrumCSV(samples, sampleRate) {
  const { real, imag } = fftReal(samples);
  const n = real.length;
  const rows = [['bin', 'cycles_per_sample', 'hz', 'magnitude', 'phase_rad']];
  const half = Math.floor(n / 2) + 1;
  for (let k = 0; k < half; k++) {
    rows.push([String(k), (k / n).toFixed(8), (k * sampleRate / n).toFixed(4),
      Math.hypot(real[k], imag[k]).toFixed(8), Math.atan2(imag[k], real[k]).toFixed(8)]);
  }
  return rows.join('\n') + '\n';
}

/** Full experiment snapshot. Pure data, no functions, no browser globals. */
function exportExperimentJSON(experiment) {
  const { config, coeffs, bode, spectrum, diagnostics } = experiment;
  return JSON.stringify({
    schemaVersion: SCHEMA_VERSION,
    generator: 'fft-filter-bench',
    note: 'Synthetic benchmark stimulus and computed DSP results. No measured hardware data.',
    config,
    coefficients: coeffs,
    stability: biquadStability(coeffs),
    diagnostics,
    bode: {
      freq: Array.from(bode.freq), mag: Array.from(bode.mag),
      phase: Array.from(bode.phase), grpDelay: Array.from(bode.grpDelay)
    },
    spectrum: spectrum ? { bins: Array.from(spectrum.bins), mag: Array.from(spectrum.mag) } : null
  }, null, 2);
}

/** Minimal 16-bit mono PCM WAV (RIFF/WAVE), returned as a Uint8Array. */
function exportWAV(samples, sampleRate = 48000) {
  if (!Number.isSafeInteger(sampleRate) || sampleRate < 1 || sampleRate > 0xFFFFFFFF) {
    throw new RangeError(`sampleRate must be an integer in [1, 4294967295], got ${sampleRate}`);
  }
  const n = samples.length;
  for (let i = 0; i < n; i++) {
    if (!Number.isFinite(samples[i])) throw new RangeError(`sample ${i} is not finite`);
  }
  const buffer = new ArrayBuffer(44 + n * 2);
  const view = new DataView(buffer);
  const ascii = (offset, text) => { for (let i = 0; i < text.length; i++) view.setUint8(offset + i, text.charCodeAt(i)); };
  ascii(0, 'RIFF'); view.setUint32(4, 36 + n * 2, true); ascii(8, 'WAVE');
  ascii(12, 'fmt '); view.setUint32(16, 16, true);
  view.setUint16(20, 1, true); view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true); view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true); view.setUint16(34, 16, true);
  ascii(36, 'data'); view.setUint32(40, n * 2, true);
  for (let i = 0; i < n; i++) {
    const v = clamp(samples[i], -1, 1);
    view.setInt16(44 + i * 2, Math.round(v * 32767), true);
  }
  return new Uint8Array(buffer);
}

