function renderPoleZeroSVG(data, width = 400, height = 400) {
  const cx = width / 2, cy = height / 2, scale = Math.min(width, height) * 0.4;
  let svg = `<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Pole zero plot">\n`;
  svg += `  <title>Pole-zero plane</title><desc>Zeros as circles, poles as crosses, dashed unit circle.</desc>\n`;
  svg += `  <rect width="${width}" height="${height}" fill="#10182a"/>\n`;
  for (let r = 0.25; r <= 1.5; r += 0.25) svg += `  <circle cx="${cx}" cy="${cy}" r="${r * scale}" fill="none" stroke="#26344f" stroke-width="0.5"/>\n`;
  svg += `  <line x1="0" y1="${cy}" x2="${width}" y2="${cy}" stroke="#3b4a68" stroke-width="1"/>\n`;
  svg += `  <line x1="${cx}" y1="0" x2="${cx}" y2="${height}" stroke="#3b4a68" stroke-width="1"/>\n`;
  svg += `  <circle cx="${cx}" cy="${cy}" r="${scale}" fill="none" stroke="#4ade80" stroke-width="2" stroke-dasharray="4,4"/>\n`;
  for (const z of data.zeros) {
    svg += `  <circle cx="${cx + z.x * scale}" cy="${cy - z.y * scale}" r="8" fill="none" stroke="#0ff" stroke-width="2"/>\n`;
  }
  for (const p of data.poles) {
    const x = cx + p.x * scale, y = cy - p.y * scale, s = 8;
    svg += `  <line x1="${x - s}" y1="${y - s}" x2="${x + s}" y2="${y + s}" stroke="#f00" stroke-width="2"/>\n`;
    svg += `  <line x1="${x + s}" y1="${y - s}" x2="${x - s}" y2="${y + s}" stroke="#f00" stroke-width="2"/>\n`;
  }
  return svg + '</svg>';
}

function bodeSVG(bode, key, color, label, width = 600, height = 300, fixedRange) {
  const margin = { top: 20, right: 20, bottom: 40, left: 62 };
  const plotW = width - margin.left - margin.right, plotH = height - margin.top - margin.bottom;
  const values = Array.from(bode[key]);
  let min = fixedRange ? fixedRange[0] : Math.min(...values);
  let max = fixedRange ? fixedRange[1] : Math.max(...values);
  if (!Number.isFinite(min) || !Number.isFinite(max)) { min = -1; max = 1; }
  else if (max - min < EPS) { min -= 1; max += 1; }
  const range = max - min;
  let svg = `<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${label}">\n`;
  svg += `  <title>${label}</title><desc>Biquad response versus normalized frequency.</desc>\n`;
  svg += `  <rect width="${width}" height="${height}" fill="#10182a"/>\n`;
  for (let t = 0; t <= 1.0001; t += 0.25) {
    const y = margin.top + plotH * (1 - t);
    svg += `  <line x1="${margin.left}" y1="${y}" x2="${width - margin.right}" y2="${y}" stroke="#26344f" stroke-width="0.5"/>\n`;
    svg += `  <text x="${margin.left - 6}" y="${y + 4}" text-anchor="end" fill="#8296b4" font-size="10">${(min + t * range).toFixed(1)}</text>\n`;
  }
  for (let f = 0; f <= 1.0001; f += 0.1) {
    const x = margin.left + plotW * f;
    svg += `  <line x1="${x}" y1="${margin.top}" x2="${x}" y2="${height - margin.bottom}" stroke="#26344f" stroke-width="0.5"/>\n`;
  }
  svg += `  <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}" stroke="#3b4a68"/>\n`;
  svg += `  <line x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}" stroke="#3b4a68"/>\n`;
  const points = [];
  let broken = true;
  for (let i = 0; i < bode.freq.length; i++) {
    const v = values[i];
    if (!Number.isFinite(v)) { broken = true; continue; }
    const x = margin.left + plotW * bode.freq[i];
    const y = margin.top + plotH * (1 - (v - min) / range);
    points.push((broken ? 'M ' : 'L ') + `${x.toFixed(2)} ${y.toFixed(2)}`);
    broken = false;
  }
  svg += `  <path d="${points.join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>\n`;
  svg += `  <text x="${width / 2}" y="${height - 6}" text-anchor="middle" fill="#a9bcd8" font-size="11">Normalized frequency (x PI rad/sample)</text>\n`;
  svg += `  <text x="14" y="${margin.top + plotH / 2}" text-anchor="middle" fill="#a9bcd8" font-size="11" transform="rotate(-90, 14, ${margin.top + plotH / 2})">${label}</text>\n`;
  return svg + '</svg>';
}

function renderBodeMagSVG(bode, width = 600, height = 300) {
  return bodeSVG(bode, 'mag', '#0f0', 'Magnitude (dB)', width, height);
}
function renderBodePhaseSVG(bode, width = 600, height = 300) {
  return bodeSVG(bode, 'phase', '#0ff', 'Phase (rad)', width, height);
}
function renderBodeGroupDelaySVG(bode, width = 600, height = 300) {
  // Group delay diverges at transmission zeros, so clamp for display only.
  const clamped = { freq: bode.freq, grpDelay: Array.from(bode.grpDelay, v => clamp(v, -100, 100)) };
  return bodeSVG(clamped, 'grpDelay', '#ff0', 'Group delay (samples)', width, height);
}

